
(()=>{'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const config=JSON.parse(document.getElementById('data').textContent);
const image=config.logo,portrait=config.avatar;
const categories=['Digital Growth & Commerce','Digital Products & Technology','Leadership & International Scale','Brand, Marketing & Transformation'];
const slug=()=>new URLSearchParams(location.search).get('firma')||location.hash.match(/^#\/([\w-]+)$/)?.[1]||location.pathname.split('/').filter(Boolean).at(-1)?.replace(/\.html$/,'')||'';
function readFit(s){
 if(window.__applicationData?.slug===s)return {items:window.__applicationData.jobFit||[]};
 return {items:[]};
}
function launch(a){const s=a.slug||slug();const fit=readFit(s);const matches=(fit.items||[]).filter(x=>x.requirement?.trim()&&x.evidence?.trim()).slice(0,3);
let existing=document.getElementById('journey88');if(existing)existing.remove();
const wrap=document.createElement('div');wrap.id='journey88';wrap.setAttribute('aria-label','Persönliche Bewerbung – geführter Einstieg');
const intro=`<section class="j88-page j88-arrival" id="j88-0"><div class="j88-content"><img class="j88-logo" src="${image}" alt="BS-Monogramm"><span class="j88-kicker">BEYOND THE CV / PERSONAL INVITATION</span><h1>Mehr als ein Lebenslauf.<br><span class="j88-gradient">Ein persönlicher Einblick.</span></h1><p>Eine persönliche Bewerbung für ${esc(a.company||'Ihr Unternehmen')}</p>${a.slug==='q-railing-product-marketing'?'<p style="font-size:12px;color:#8ca8bc">PERSÖNLICHER BEWERBUNGSENTWURF · NOCH NICHT FREIGEGEBEN</p>':''}<button class="j88-button" data-next="1">Persönliche Nachricht lesen ↓</button><span class="j88-scroll">01 / 05 · ARRIVAL</span></div></section>`;
const personal=`<section class="j88-page" id="j88-1"><div class="j88-content j88-personal"><div><span class="j88-kicker">02 / 05 · PERSÖNLICHE ANSPRACHE</span><h2>${esc(a.greeting||'Guten Tag,')}</h2><p>${esc(a.personalNote||'Vielen Dank, dass Sie sich Zeit für meine Bewerbung nehmen.')}</p><p>${esc(a.motivation||'')}</p>${a.letter?`<details class="j88-letter"><summary>Mein vollständiges Motivationsschreiben <span aria-hidden="true">↗</span></summary><div class="j96-letter-body">${esc(a.letter).split(/\n\n/).map(p=>`<p>${p.replace(/\n/g,"<br>")}</p>`).join("")}</div></details>`:'<div class="j88-placeholder">Das Motivationsschreiben kann im Content Studio ergänzt werden.</div>'}<p class="j88-note">${esc(a.role||'')} · ${esc(a.company||'')}</p><button class="j88-button" data-next="2">Meine Erfahrung auf einen Blick ↓</button></div><img class="j88-portrait" src="${portrait}" alt="Illustration von Benedict Steinheil"></div></section>`;
const snapshot=`<section class="j88-page" id="j88-2"><div class="j88-content"><span class="j88-kicker">03 / 05 · EXECUTIVE SNAPSHOT</span><h2>Digital Sales.<br><span class="j88-gradient">Technologie. Führung.</span></h2><p>Rund zehn Jahre Erfahrung in digitalem Marketing und Vertrieb – mit Schwerpunkt auf internationalem E-Commerce, digitalen Produkten und Teamführung.</p><div class="j88-stats"><div class="j88-stat"><strong>10 Mio. €+</strong><span>Online-Umsatz nach drei Jahren (zuvor unter 5 Mio. €)</span></div><div class="j88-stat"><strong>250+</strong><span>Leads pro Monat durch den 3D-Konfigurator</span></div><div class="j88-stat"><strong>Bis zu 9</strong><span>Mitarbeiter geführt</span></div><div class="j88-stat"><strong>13</strong><span>Internationale Tochtergesellschaften, plus 3 Vertriebspartner</span></div></div><p class="j88-note">Die Umsatzentwicklung ist ein Unternehmensergebnis, zu dem ich wesentlich beigetragen habe.</p><button class="j88-button" data-next="3">Warum ich zu dieser Stelle passe ↓</button></div></section>`;
const fitCards=matches.length?matches.map((x,i)=>`<article class="j88-fit"><span class="j88-kicker">PASSUNG 0${i+1} / 03</span><strong>${esc(x.requirement)}</strong><p>${esc(x.evidence)}</p><button data-world-go="${Math.min(3,Math.max(0,Number(x.world)||0))}">Projektkontext entdecken →</button>${/^https:\/\//i.test(x.link||'')?`<p><a href="${esc(x.link)}" target="_blank" rel="noopener noreferrer" style="color:#83dfff">Referenz ansehen ↗</a></p>`:''}</article>`).join(''):'<div class="j88-placeholder">Die individuelle Passung zur Stellenanzeige ist noch nicht hinterlegt. Ergänze im Bereich „JOB FIT“ bis zu drei konkrete Anforderungen und passende Erfahrungsnachweise. Es werden keine Stellenanforderungen erfunden.</div>';
const fitSection=`<section class="j88-page" id="j88-3"><div class="j88-content"><span class="j88-kicker">04 / 05 · PERSONALIZED JOB FIT</span><h2>Warum diese Position<br><span class="j88-gradient">zu meinem Profil passt.</span></h2><p>Die Verbindung zwischen den Anforderungen der Position und meiner bisherigen Erfahrung.</p><div class="j88-fitgrid">${fitCards}</div><button class="j88-button" data-next="4">Meine Kompetenzwelten entdecken ↓</button></div></section>`;
const end=`<section class="j88-page" id="j88-4"><div class="j88-content" style="text-align:center"><span class="j88-kicker">05 / 05 · BEYOND THE CV</span><h2>Hinter den Zahlen<br><span class="j88-gradient">steckt mehr.</span></h2><p>Entdecken Sie die Projekte, Entscheidungen und Erfahrungen hinter meiner Bewerbung – in vier interaktiven Kompetenzwelten.</p><div class="j88-actions" style="justify-content:center"><button class="j88-button" id="j88-enter">Kompetenzwelten betreten →</button><button class="j88-button secondary" id="j88-career">Career Journey ansehen</button></div></div></section>`;
wrap.innerHTML=`<div class="j88-top"><span>BENEDICT STEINHEIL <span class="j96-top-divider">/</span> ${esc(a.role||"BEYOND THE CV")}</span><button id="j88-skip">CV direkt ansehen ↗</button></div><nav class="j88-progress" aria-label="Abschnitte">${[0,1,2,3,4].map(i=>`<button data-next="${i}" aria-label="${["Arrival","Persönliche Ansprache","Executive Snapshot","Passung zur Stelle","Kompetenzwelten"][i]}" ${i===0?'aria-current="step"':''}></button>`).join('')}</nav>`+intro+personal+snapshot+fitSection+end;
document.body.append(wrap);document.body.classList.add('journey88-active');
const go=i=>{const el=wrap.querySelector('#j88-'+i);if(!el)return;wrap.scrollTo({top:el.offsetTop,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};
const exit=()=>{window.__personalJourneyScroll=wrap.scrollTop;wrap.remove();document.body.classList.remove('journey88-active');if(window.__applicationData?.slug===a.slug){document.body.classList.add('personalized-portal');document.getElementById('backToApplication')?.focus({preventScroll:true})}else{document.getElementById('homeBtn')?.focus({preventScroll:true})}};
wrap.querySelectorAll('[data-next]').forEach(b=>b.addEventListener('click',()=>go(Number(b.dataset.next))));
wrap.querySelector('#j88-skip').onclick=exit;wrap.querySelector('#j88-enter').onclick=exit;
wrap.querySelector('#j88-career').onclick=()=>{exit();document.getElementById('careerBtn')?.click()};
wrap.querySelectorAll('[data-world-go]').forEach(b=>b.onclick=()=>{const w=Number(b.dataset.worldGo);exit();document.querySelector(`#nodes [data-world="${w}"]`)?.click()});
wrap.addEventListener('scroll',()=>{const i=Math.min(4,Math.round(wrap.scrollTop/Math.max(1,wrap.clientHeight)));wrap.querySelectorAll('.j88-progress button').forEach((b,j)=>{if(j===i)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')})},{passive:true});
wrap.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();exit()}});
// Keep keyboard focus inside the full-screen journey, including on long letters.
wrap.setAttribute('role','dialog');wrap.setAttribute('aria-modal','true');
wrap.setAttribute('aria-label','Persönliche Bewerbung von Benedict Steinheil');
wrap.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const focusable=[...wrap.querySelectorAll('a[href],button:not([disabled]),summary,[tabindex]:not([tabindex="-1"])')].filter(x=>x.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
wrap.querySelector('#j88-skip').focus({preventScroll:true});
if(window.__personalJourneyScroll){requestAnimationFrame(()=>{wrap.scrollTop=window.__personalJourneyScroll})}
}
window.__launchPersonalJourney=launch;
if(window.__applicationData){setTimeout(()=>launch(window.__applicationData),90)}
// Optional preview without publishing personal data; placeholder-only demo, never a fabricated company application.
if(new URLSearchParams(location.search).get('preview')==='journey'){setTimeout(()=>launch({slug:'preview',company:'Ihr Unternehmen',role:'Ihre ausgeschriebene Position',greeting:'Guten Tag,',personalNote:'Diese Ansicht zeigt den Ablauf einer personalisierten Bewerbung.',motivation:'Hier erscheint Ihre individuell formulierte Motivation. Die Inhalte werden aus einer gespeicherten Bewerbung übernommen.',letter:''}),60)}
})();
